```tsx
import React, { useState, useEffect, useMemo } from 'react';
import { StaffMember, Shift, ShiftSettings } from '../types';
import { BackArrowIcon, DiceIcon, WalletIcon, CheckIcon } from './Icons';

interface DiceGameProps {
    onGoBack: () => void;
    staff: StaffMember[];
    shiftSettings?: ShiftSettings;
}

interface PlayerResult {
    id: string;
    name: string;
    icon: string;
    dice1: number;
    dice2: number;
    total: number;
    isRolling: boolean;
}

const DiceGame: React.FC<DiceGameProps> = ({ onGoBack, staff, shiftSettings }) => {
    const [participants, setParticipants] = useState<PlayerResult[]>([]);
    const [gameStatus, setGameStatus] = useState<'idle' | 'rolling' | 'finished'>('idle');
    const [loserScore, setLoserScore] = useState<number | null>(null);

    // CALCOLO TURNO ATTIVO (Logica duplicata da TillSelection per sicurezza)
    const activeShift = useMemo(() => {
        const now = new Date();
        const hour = now.getHours();
        const calculationDate = new Date(now);
        if (hour < 8) {
            calculationDate.setDate(calculationDate.getDate() - 1);
        }
        calculationDate.setHours(12, 0, 0, 0);

        const anchorDateStr = shiftSettings?.anchorDate || '2025-12-10';
        const anchorShift = shiftSettings?.anchorShift || 'd';

        const anchorDate = new Date(anchorDateStr);
        anchorDate.setHours(12, 0, 0, 0);

        const diffTime = calculationDate.getTime() - anchorDate.getTime();
        const diffDays = Math.round(diffTime / (1000 * 60 * 60 * 24));

        const shifts = ['a', 'b', 'c', 'd'];
        const anchorIndex = shifts.indexOf(anchorShift.toLowerCase());

        let shiftIndex = (anchorIndex + diffDays) % 4;
        if (shiftIndex < 0) shiftIndex += 4;

        if (hour >= 20 || hour < 8) {
            shiftIndex = (shiftIndex - 1);
            if (shiftIndex < 0) shiftIndex += 4;
        }

        return shifts[shiftIndex] as Shift;
    }, [shiftSettings]);

    // Inizializza partecipanti in base al turno ATTIVO
    useEffect(() => {
        // Filtra solo staff del turno attivo ED escludi utenti con nome "Cassa"
        const filtered = staff.filter(s => 
            s.shift === activeShift && 
            !s.name.toLowerCase().includes('cassa')
        );

        setParticipants(filtered.map(s => ({
            id: s.id,
            name: s.name,
            icon: s.icon || '👤',
            dice1: 1,
            dice2: 1,
            total: 0,
            isRolling: false
        })));
        setGameStatus('idle');
        setLoserScore(null);
    }, [activeShift, staff]);

    const handleRoll = () => {
        if (participants.length < 2) return alert("Servono almeno 2 partecipanti!");
        setGameStatus('rolling');
        setLoserScore(null);

        // Set all to rolling
        const rollingParticipants = participants.map(p => ({...p, isRolling: true, total: 0}));
        setParticipants(rollingParticipants);

        // Simuliamo il tempo di lancio (animazione CSS gestisce il movimento)
        setTimeout(() => {
            finalizeResults();
        }, 1500); // 1.5 secondi di roll
    };

    const finalizeResults = () => {
        const finalResults = participants.map(p => {
            const d1 = Math.floor(Math.random() * 6) + 1;
            const d2 = Math.floor(Math.random() * 6) + 1;
            return {
                ...p,
                dice1: d1,
                dice2: d2,
                total: d1 + d2,
                isRolling: false
            };
        });

        const minScore = Math.min(...finalResults.map(p => p.total));
        finalResults.sort((a,b) => a.total - b.total);

        setParticipants(finalResults);
        setLoserScore(minScore);
        setGameStatus('finished');
    };

    const toggleParticipant = (id: string) => {
        if (gameStatus === 'rolling') return;
        const exists = participants.find(p => p.id === id);
        if (exists) {
            setParticipants(participants.filter(p => p.id !== id));
        } else {
            const s = staff.find(st => st.id === id);
            if (s) {
                setParticipants([...participants, {
                    id: s.id,
                    name: s.name,
                    icon: s.icon || '👤',
                    dice1: 1,
                    dice2: 1,
                    total: 0,
                    isRolling: false
                }]);
            }
        }
        setGameStatus('idle');
    };

    // Componente Dado 3D
    const Die3D = ({ val, rolling }: { val: number, rolling: boolean }) => {
        const rotationMap: {[key: number]: string} = {
            1: 'rotateX(0deg) rotateY(0deg)',
            6: 'rotateX(180deg) rotateY(0deg)',
            2: 'rotateY(-90deg)',
            5: 'rotateY(90deg)',
            3: 'rotateX(-90deg)',
            4: 'rotateX(90deg)'
        };

        return (
            <div className="scene w-10 h-10 md:w-12 md:h-12">
                <div className={`cube ${rolling ? 'rolling' : ''}`} 
                     style={{ transform: rolling ? undefined : rotationMap[val] }}>

                    {/* FACCIA 1 */}
                    <div className="cube-face cube-face-front">
                        <div className="w-3 h-3 bg-black rounded-full absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2"></div>
                    </div>
                    {/* FACCIA 2 */}
                    <div className="cube-face cube-face-right grid grid-cols-3 grid-rows-3 p-1.5">
                        <div className="col-start-1 row-start-1 w-2.5 h-2.5 bg-black rounded-full justify-self-center self-center shadow-inner"></div>
                        <div className="col-start-3 row-start-3 w-2.5 h-2.5 bg-black rounded-full justify-self-center self-center shadow-inner"></div>
                    </div>
                    {/* FACCIA 3 */}
                    <div className="cube-face cube-face-left grid grid-cols-3 grid-rows-3 p-1.5">
                        <div className="col-start-1 row-start-1 w-2.5 h-2.5 bg-black rounded-full justify-self-center self-center shadow-inner"></div>
                        <div className="col-start-2 row-start-2 w-2.5 h-2.5 bg-black rounded-full justify-self-center self-center shadow-inner"></div>
                        <div className="col-start-3 row-start-3 w-2.5 h-2.5 bg-black rounded-full justify-self-center self-center shadow-inner"></div>
                    </div>
                    {/* FACCIA 4 */}
                    <div className="cube-face cube-face-bottom grid grid-cols-3 grid-rows-3 p-1.5">
                        <div className="col-start-1 row-start-1 w-2.5 h-2.5 bg-black rounded-full justify-self-center self-center shadow-inner"></div>
                        <div className="col-start-3 row-start-1 w-2.5 h-2.5 bg-black rounded-full justify-self-center self-center shadow-inner"></div>
                        <div className="col-start-1 row-start-3 w-2.5 h-2.5 bg-black rounded-full justify-self-center self-center shadow-inner"></div>
                        <div className="col-start-3 row-start-3 w-2.5 h-2.5 bg-black rounded-full justify-self-center self-center shadow-inner"></div>
                    </div>
                    {/* FACCIA 5 */}
                    <div className="cube-face cube-face-top grid grid-cols-3 grid-rows-3 p-1.5">
                        <div className="col-start-1 row-start-1 w-2.5 h-2.5 bg-black rounded-full justify-self-center self-center shadow-inner"></div>
                        <div className="col-start-3 row-start-1 w-2.5 h-2.5 bg-black rounded-full justify-self-center self-center shadow-inner"></div>
                        <div className="col-start-2 row-start-2 w-2.5 h-2.5 bg-black rounded-full justify-self-center self-center shadow-inner"></div>
                        <div className="col-start-1 row-start-3 w-2.5 h-2.5 bg-black rounded-full justify-self-center self-center shadow-inner"></div>
                        <div className="col-start-3 row-start-3 w-2.5 h-2.5 bg-black rounded-full justify-self-center self-center shadow-inner"></div>
                    </div>
                    {/* FACCIA 6 */}
                    <div className="cube-face cube-face-back grid grid-cols-3 grid-rows-3 p-1.5">
                        <div className="col-start-1 row-start-1 w-2.5 h-2.5 bg-black rounded-full justify-self-center self-center shadow-inner"></div>
                        <div className="col-start-3 row-start-1 w-2.5 h-2.5 bg-black rounded-full justify-self-center self-center shadow-inner"></div>
                        <div className="col-start-1 row-start-2 w-2.5 h-2.5 bg-black rounded-full justify-self-center self-center shadow-inner"></div>
                        <div className="col-start-3 row-start-2 w-2.5 h-2.5 bg-black rounded-full justify-self-center self-center shadow-inner"></div>
                        <div className="col-start-1 row-start-3 w-2.5 h-2.5 bg-black rounded-full justify-self-center self-center shadow-inner"></div>
                        <div className="col-start-3 row-start-3 w-2.5 h-2.5 bg-black rounded-full justify-self-center self-center shadow-inner"></div>
                    </div>
                </div>
            </div>
        );
    };

    // Filtra lista staff globale per mostrare solo il turno corrente (per permettere di ri-aggiungere qualcuno se deselezionato)
    // Esclude sempre cassa
    const currentShiftStaffList = useMemo(() => {
        return staff.filter(s => s.shift === activeShift && !s.name.toLowerCase().includes('cassa'));
    }, [staff, activeShift]);

    return (
        <div className="flex flex-col min-h-screen bg-blue-50 font-sans">
            <header className="bg-blue-600 text-white p-4 shadow-lg sticky top-0 z-10 border-b-4 border-blue-800 flex justify-between items-center">
                <button onClick={onGoBack} className="flex items-center gap-1 font-bold hover:text-white/80 transition-colors">
                    <BackArrowIcon className="h-5 w-5" /> Esci
                </button>
                <h1 className="text-xl font-black uppercase tracking-widest flex items-center gap-2">
                    <DiceIcon className="h-6 w-6" /> Chi Paga?
                </h1>
                <div className="w-10"></div>
            </header>

            <main className="flex-grow p-4 w-full max-w-4xl mx-auto space-y-6">

                {/* SELEZIONE PARTECIPANTI (Cards) */}
                <div className="bg-white p-4 rounded-xl shadow-md border border-blue-200">
                    <div className="flex justify-between items-center mb-4">
                        <h2 className="text-sm font-bold text-blue-800 uppercase flex items-center gap-2">
                            Partecipanti (Turno {activeShift.toUpperCase()})
                        </h2>
                        <span className="bg-blue-100 text-blue-800 text-xs font-bold px-2 py-1 rounded-full">
                            {participants.length}
                        </span>
                    </div>

                    <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-6 gap-2">
                        {currentShiftStaffList.map(s => {
                            const isSelected = participants.some(p => p.id === s.id);
                            return (
                                <button 
                                    key={s.id} 
                                    onClick={() => toggleParticipant(s.id)}
                                    className={`
                                        relative flex flex-col items-center justify-center p-2 rounded-lg border transition-all duration-200
                                        ${isSelected 
                                            ? 'bg-blue-50 border-blue-500 shadow-sm' 
                                            : 'bg-slate-50 border-slate-200 opacity-60 hover:opacity-100 hover:border-blue-300'
                                        }
                                    `}
                                >
                                    {isSelected && (
                                        <div className="absolute -top-1.5 -right-1.5 bg-green-500 text-white rounded-full p-0.5 shadow-sm scale-75">
                                            <CheckIcon className="h-3 w-3" />
                                        </div>
                                    )}
                                    <div className="text-lg mb-1">{s.icon || '👤'}</div>
                                    <span className={`text-[9px] font-bold truncate w-full text-center ${isSelected ? 'text-blue-900' : 'text-slate-500'}`}>
                                        {s.name.split(' ')[0]}
                                    </span>
                                </button>
                            );
                        })}
                    </div>
                </div>

                {/* GAME AREA */}
                <div className="space-y-4">
                    {participants.length === 0 && (
                        <div className="text-center py-10 text-slate-400 italic">
                            Nessun partecipante selezionato.
                        </div>
                    )}

                    {participants.map((player) => {
                        const isLoser = gameStatus === 'finished' && player.total === loserScore;
                        return (
                            <div 
                                key={player.id} 
                                className={`
                                    relative flex items-center justify-between p-4 rounded-2xl border-2 transition-all duration-500
                                    ${isLoser ? 'bg-red-50 border-red-500 shadow-xl scale-105 z-10' : 'bg-white border-slate-100 shadow-sm'}
                                `}
                            >
                                <div className="flex items-center gap-3">
                                    <div className="text-3xl">{player.icon}</div>
                                    <div>
                                        <div className="font-bold text-slate-800">{player.name}</div>
                                        {isLoser && <div className="text-[10px] font-black text-red-600 uppercase bg-red-100 px-2 py-0.5 rounded inline-block animate-pulse">Paga Tutto!</div>}
                                    </div>
                                </div>

                                <div className="flex items-center gap-4">
                                    <div className="flex gap-4">
                                        <Die3D val={player.dice1} rolling={player.isRolling} />
                                        <Die3D val={player.dice2} rolling={player.isRolling} />
                                    </div>
                                    <div className="w-12 text-center">
                                        {!player.isRolling && player.total > 0 && (
                                            <span className={`text-2xl font-black animate-fade-in ${isLoser ? 'text-red-600' : 'text-slate-700'}`}>
                                                {player.total}
                                            </span>
                                        )}
                                    </div>
                                </div>

                                {isLoser && (
                                    <div className="absolute -right-2 -top-2 bg-red-600 text-white p-2 rounded-full shadow-lg animate-bounce">
                                        <WalletIcon className="h-6 w-6" />
                                    </div>
                                )}
                            </div>
                        );
                    })}
                </div>

            </main>

            <div className="sticky bottom-4 px-4 w-full max-w-4xl mx-auto">
                <button 
                    onClick={handleRoll}
                    disabled={gameStatus === 'rolling' || participants.length < 2}
                    className="w-full bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 text-white font-black py-4 rounded-2xl shadow-xl uppercase tracking-wider text-xl transition-transform active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed border-b-4 border-blue-800"
                >
                    {gameStatus === 'rolling' ? 'Lancio in corso...' : '🎲 Lancia Dadi'}
                </button>
            </div>
        </div>
    );
};

export default DiceGame;
